// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    address immutable bankEoa = address(0xBEEF);

    function setUp() public {
        // bank must be a plain EOA so that transfer(FEE_AMOUNT) to bank succeeds
        vm.prank(bankEoa);
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.roll(1); // deterministic difficulty so win/loss is computable
        vm.warp(t);
        vm.deal(actor, 10);
        vm.prank(actor);
        bool ok;
        try c.play{value: 10}() { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                // General rule: a winning play empties the pot completely.
                assertTrue(c.pot() == 0, "winning play must leave pot at 0");
            }
        }
    }
}
